//autogenerated:yes
//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
)

func TestEnum_PREFLIGHT_STORAGE_PARAMETER_ACTION(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.PREFLIGHT_STORAGE_PARAMETER_ACTION
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.PARAM_READ_PERSISTENT.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.PREFLIGHT_STORAGE_PARAMETER_ACTION
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.PARAM_READ_PERSISTENT, dec)
	})
}
